import React from "react";
import "./ProductCard.css";

const ProductCard = ({ product }) => {
    const navigate = useNavigate();

    const handleViewDetail = () => {
        // Điều hướng sang trang chi tiết theo id của sản phẩm
        navigate(`/product/${product.id}`);
    };
    return (
        <div className="furniture-card h-100">

            {/* Badge */}
            <div className="furniture-badge">
                Collection
            </div>

            {/* Image */}
            <div className="furniture-img-container">

                <img
                    src={
                        product.imageUrl
                            ? product.imageUrl
                            : "https://placehold.co/400x400?text=No+Image"
                    }
                    alt={product.name}
                    className="furniture-image"
                    onError={(e) => {
                        e.target.onerror = null;
                        e.target.src =
                            "https://placehold.co/400x400?text=No+Image";
                    }}
                />

            </div>

            {/* Content */}
            <div className="furniture-content">

                <span className="furniture-category">
                    {product.categoryProductName || "Nội thất"}
                </span>

                <h3
                    className="furniture-title"
                    title={product.name}
                >
                    {product.name}
                </h3>

                <p className="furniture-description">
                    {
                        product.description ||
                        "Thiết kế tinh tế, chất liệu cao cấp."
                    }
                </p>

                <div className="furniture-footer">

                    <div className="furniture-price">
                        {
                            typeof product.price === "number"
                                ? product.price.toLocaleString(
                                    "vi-VN",
                                    {
                                        style: "currency",
                                        currency: "VND"
                                    }
                                )
                                : product.price
                        }
                    </div>

                    <button className="btn-furniture">
                        Xem chi tiết
                    </button>

                </div>

            </div>

        </div>
    );
};

export default ProductCard;
